import {
  Button as AriaButton,
  SelectionIndicator,
  Tab as AriaTab,
  TabList as AriaTabList,
  TabPanel as AriaTabPanel,
  Tabs as AriaTabs,
} from "react-aria-components";
import type {
  TabListProps as AriaTabListProps,
  TabPanelProps as AriaTabPanelProps,
  TabProps as AriaTabProps,
  TabsProps as AriaTabsProps,
} from "react-aria-components";
import { createContext, useContext, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { CSSProperties, ReactNode, Ref } from "react";
import { ChevronLeft, ChevronRight } from "./icons";
import { ScrollArea } from "./ScrollArea";
import { roleSize, type ControlSize } from "./controlSize";
import "./Tabs.css";

type TabsOrientation = "horizontal" | "vertical";

// RAC emits data-orientation on Tabs/TabList but NOT on individual Tab elements
// (TabRenderProps has no orientation). Relay it via context so the per-tab selected
// indicator can react on the same element — no descendant combinator (contract §6).
// `size` rides along for the same reason: it is set once on Tabs but every Tab has to render it
// (height + the size-matched type role), and RAC hands the Tab no channel to read it from.
export type TabsSize = ControlSize;
export type TabsVariant = "flat" | "contained" | "quiet";
export type TabsOverflow = "scroll" | "page" | "wrap";

// `variant` and `overflow` ride the same context as `size`: they are set once on Tabs, and the list,
// every Tab and the row around them each have to render them as their own `data-*`.
const TabsContext = createContext<{
  orientation: TabsOrientation;
  size: TabsSize;
  variant: TabsVariant;
  overflow: TabsOverflow;
  isFullWidth: boolean;
}>({
  orientation: "horizontal",
  size: "medium",
  variant: "flat",
  overflow: "scroll",
  isFullWidth: false,
});

/** Common Tabs props — the axes independent of `overflow`. */
export interface TabsBaseProps extends Omit<AriaTabsProps, "className"> {
  /**
   * Visual variant. `flat` marks the selected tab with an indicator on a rail; `contained` draws
   * the selected tab as a filled box instead, with no rail. `quiet` uses primary versus muted
   * ink alone, without a rail or indicator.
   *
   * @default "flat"
   */
  variant?: TabsVariant;
  /**
   * Size axis (tab height + label type role). The outer sizes use the small/large type roles.
   *
   * @default "medium"
   */
  size?: TabsSize;
  /**
   * Fill the row. Horizontal tabs share it in equal cells, and a contained tab's selected box spans
   * its cell, as on a kiosk category bar. With `overflow="wrap"` the cells become a grid of equal
   * columns, as many per row as `minTabWidth` allows. Off, each tab is as wide as its label. A
   * vertical list already spans its column, so this changes nothing there.
   *
   * @default false
   */
  isFullWidth?: boolean;
}

/**
 * Tabs props.
 *
 * `overflow="wrap"` requires `variant="contained"`, at the type level (component-contract.md §2).
 * A flat tab's indicator sits on the rail under the list, and a wrapped row has no rail of its own to
 * meet it; a contained tab carries its selection in its own fill, so it can wrap.
 */
export type TabsProps = TabsBaseProps &
  (
    | {
        /**
         * What happens when the tabs are wider than the row. `scroll` scrolls the strip; `page` adds
         * previous/next arrows at whichever end hides tabs; `wrap` flows the tabs onto as many rows as
         * they need, and needs `variant="contained"`. Horizontal only: a vertical list always
         * scrolls.
         *
         * Keyboard navigation stays one-dimensional in every mode: the arrow keys move through the
         * tabs in order, across rows when they wrap (React Aria's tab keyboard model).
         *
         * @default "scroll"
         */
        overflow?: "scroll" | "page";
      }
    | { variant: "contained"; overflow: "wrap" }
  ) & {
    /**
     * The narrowest a cell may be when `isFullWidth` tabs wrap: the row holds as many equal columns
     * as fit at this width, the GridList `minItemWidth` idiom. Any CSS length. Ignored unless both
     * `isFullWidth` and `overflow="wrap"` are set.
     *
     * @default "12rem"
     */
    minTabWidth?: string;
    /** Additional class. sd-tabs is always retained. */
    className?: string;
    /** Passed to the underlying div DOM node. */
    ref?: Ref<HTMLDivElement>;
  };

const widthVar = (width: string) => ({ "--sd-tabs-min-tab-width": width }) as CSSProperties;

export function Tabs({
  variant = "flat",
  size = "medium",
  isFullWidth = false,
  overflow = "scroll",
  minTabWidth = "12rem",
  className,
  style,
  orientation = "horizontal",
  ...props
}: TabsProps) {
  // The EFFECTIVE mode: paging and wrapping are horizontal arrangements, so a vertical list scrolls
  // whatever was asked, and every part emits what its CSS should act on.
  const mode: TabsOverflow = orientation === "vertical" ? "scroll" : overflow;
  // Memoized so a Tabs re-render doesn't hand every Tab a fresh context object.
  const ctx = useMemo(
    () => ({ orientation, size, variant, overflow: mode, isFullWidth }),
    [orientation, size, variant, mode, isFullWidth],
  );
  return (
    <TabsContext.Provider value={ctx}>
      <AriaTabs
        {...props}
        orientation={orientation}
        // Always injected, as GridList does: only a full-width wrapped list reads it.
        style={
          typeof style === "function"
            ? (renderProps) => ({ ...widthVar(minTabWidth), ...style(renderProps) })
            : { ...widthVar(minTabWidth), ...style }
        }
        className={className ? `sd-tabs ${className}` : "sd-tabs"}
      />
    </TabsContext.Provider>
  );
}

export interface TabListProps<T extends object = object>
  extends Omit<AriaTabListProps<T>, "className"> {
  /**
   * Content at the end of the row, after the tabs and outside the tab list: a search or an expand
   * Button. React Aria's tab list holds only tabs, so this sits beside it, takes the ordinary Tab
   * stop after the list rather than joining its arrow-key ring, and stays put while the tabs scroll.
   * Icon-only Buttons here need their own `aria-label`.
   */
  trailing?: ReactNode;
  /** Additional class. sd-tabs__list is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

/**
 * More tabs than the container is wide is the ordinary case, not an edge one: with neither
 * `flex-wrap` nor `overflow` the strip would run past its frame, its labels degrading to one
 * character per line.
 *
 * A flat list SCROLLS rather than wrapping, which is the one place this component parts from its five
 * wrap-using siblings (Toolbar · Breadcrumb · ToggleButtonGroup · TagGroup · Pagination). None of
 * them draws a RAIL: the selected indicator is `.sd-tabs__tab::after` pinned to the list's own
 * `border-block-end`, so a wrapped row 1 would show its indicator where there is no rail to meet
 * it. Scrolling keeps one row against one rail, and it is what every peer system does with tabs.
 * A CONTAINED list has no rail, which is why it alone may take `overflow="wrap"`.
 *
 * `ScrollArea` rather than a bare `overflow` for the reason it exists: it owns the scrollbar
 * chrome and the conditional tab stop, measured rather than assumed.
 *
 * `overflow="page"` adds the arrows here rather than to `ScrollArea`: Tabs is the one scroller that
 * pages today (`Carousel` owns its own controls), and a public pager on `ScrollArea` would widen a
 * contract that is "scrollbar chrome + conditional tab stop". Extract it when a second consumer
 * needs it. The arrows are for the pointer: never a tab stop, and pressing one does not take focus,
 * because the keyboard already pages. They stay named buttons, as Carousel's are, so a screen
 * reader's browse mode can still use them; React Aria's Button drops `aria-hidden`, and hiding a
 * button that can be pressed would be the less honest choice anyway. React Aria scrolls the tab
 * it focuses into view on every arrow-key move (`useSelectableCollection` → `scrollIntoViewport`).
 */
export function TabList<T extends object = object>({
  trailing,
  className,
  ...props
}: TabListProps<T>) {
  const { orientation, size, variant, overflow, isFullWidth } = useContext(TabsContext);
  const isPaged = overflow === "page";
  const scroller = useRef<HTMLDivElement>(null);
  const startPager = useRef<HTMLButtonElement>(null);
  const endPager = useRef<HTMLButtonElement>(null);
  // Which ends hide tabs. An arrow renders only at an end with something past it.
  const [hidden, setHidden] = useState({ start: false, end: false });

  // Layout, not passive: measured before paint, so the end arrow is there on the first frame
  // instead of narrowing the strip one frame late.
  useLayoutEffect(() => {
    const el = scroller.current;
    if (!isPaged || !el) return;
    const measure = () => {
      // `scrollLeft` runs from 0 toward NEGATIVE under RTL, so read its magnitude. The `1` is
      // `ScrollArea`'s own subpixel tolerance: rounded widths report a 1px range that hides nothing.
      const offset = Math.abs(el.scrollLeft);
      const start = offset > 1;
      const end = offset < el.scrollWidth - el.clientWidth - 1;
      // An arrow about to unmount may hold focus: a screen reader's cursor can press it, and
      // `preventFocusOnPress` covers only the pointer. Hand focus to the arrow that stays, so it
      // never falls to <body>.
      const focused = document.activeElement;
      if (focused === startPager.current && !start) endPager.current?.focus();
      if (focused === endPager.current && !end) startPager.current?.focus();
      setHidden((prev) => (prev.start === start && prev.end === end ? prev : { start, end }));
    };
    measure();
    el.addEventListener("scroll", measure, { passive: true });
    // The scrollport AND the list: a resize changes the former, a tab added or relabelled the latter.
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    if (el.firstElementChild) observer.observe(el.firstElementChild);
    return () => {
      el.removeEventListener("scroll", measure);
      observer.disconnect();
    };
  }, [isPaged]);

  // One viewport per press. No `behavior` here: the stylesheet owns smooth scrolling, so
  // `prefers-reduced-motion` turns it off in one place.
  const page = (toward: "start" | "end") => {
    const el = scroller.current;
    if (!el) return;
    const isRtl = getComputedStyle(el).direction === "rtl";
    el.scrollBy({ left: (toward === "end") !== isRtl ? el.clientWidth : -el.clientWidth });
  };
  const pager = (toward: "start" | "end") => (
    <AriaButton
      aria-label={toward === "start" ? "Previous tabs" : "Next tabs"}
      excludeFromTabOrder
      preventFocusOnPress
      ref={toward === "start" ? startPager : endPager}
      data-size={size}
      data-variant={variant}
      className="sd-tabs__pager"
      onPress={() => page(toward)}
    >
      {toward === "start" ? <ChevronLeft aria-hidden size="1em" /> : <ChevronRight aria-hidden size="1em" />}
    </AriaButton>
  );

  return (
    <div className="sd-tabs__bar" data-orientation={orientation}>
      {isPaged && hidden.start && pager("start")}
      <ScrollArea
        ref={scroller}
        orientation={orientation}
        data-overflow={overflow}
        data-variant={variant}
        className="sd-tabs__scroll"
      >
        <AriaTabList
          {...props}
          data-variant={variant}
          data-overflow={overflow}
          data-full-width={isFullWidth || undefined}
          className={className ? `sd-tabs__list ${className}` : "sd-tabs__list"}
        />
      </ScrollArea>
      {isPaged && hidden.end && pager("end")}
      {trailing != null && (
        <div className="sd-tabs__trailing" data-orientation={orientation} data-variant={variant}>
          {trailing}
        </div>
      )}
    </div>
  );
}

export interface TabProps extends Omit<AriaTabProps, "className"> {
  /** Additional class. sd-tabs__tab is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. (React Aria renders an `<a>` when given `href`, but
      RAC's own AriaTabProps declares ref as Ref<HTMLDivElement> — we mirror the upstream type
      verbatim. A consumer needing the ref of a link tab has to cast it.) */
  ref?: Ref<HTMLDivElement>;
}

export function Tab({ className, children, ...props }: TabProps) {
  const { orientation, size, variant, overflow, isFullWidth } = useContext(TabsContext);
  // DRIVEN by size. The role is always `label` (a tab names a control); large steps its font-size
  // up through a bespoke Cmp token in Tabs.css. A quiet tab has no indicator, so its selected tab
  // also takes the emphasized twin: weight is the second cue beside the accent ink.
  const typeClass = (isSelected: boolean) =>
    `sd-type-label-${roleSize(size)}${variant === "quiet" && isSelected ? "-emphasized" : ""}`;
  const base = (isSelected: boolean) => `sd-tabs__tab ${typeClass(isSelected)}`;
  return (
    <AriaTab
      {...props}
      data-orientation={orientation}
      data-size={size}
      data-variant={variant}
      data-full-width={isFullWidth || undefined}
      data-overflow={overflow}
      className={({ isSelected }) => (className ? `${base(isSelected)} ${className}` : base(isSelected))}
    >
      {(renderProps) => (
        <>
          {typeof children === "function" ? children(renderProps) : children}
          {/* A flat tab marks its selection with a bar, React Aria's SelectionIndicator: it renders on
              the selected tab only and slides from the previous one (a CSS transition on its
              translate). A contained tab's own fill carries the selection, so it draws none. */}
          {variant === "flat" && (
            <SelectionIndicator data-orientation={orientation} data-size={size} className="sd-tabs__indicator" />
          )}
        </>
      )}
    </AriaTab>
  );
}

export interface TabPanelProps extends Omit<AriaTabPanelProps, "className"> {
  /** Additional class. sd-tabs__panel is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function TabPanel({ className, ...props }: TabPanelProps) {
  return (
    <AriaTabPanel
      {...props}
      className={
        className
          ? `sd-tabs__panel sd-type-body-medium ${className}`
          : "sd-tabs__panel sd-type-body-medium"
      }
    />
  );
}

.sd-tabs {
  display: flex;
  gap: var(--sd-tabs-gap);
}
.sd-tabs[data-orientation="horizontal"] {
  flex-direction: column;
}
.sd-tabs[data-orientation="vertical"] {
  flex-direction: row;
  align-items: flex-start;
}

/* bar — the tab row: [pager] scrollport [pager] trailing. It owns no look: the rail stays on the
   list, and the pager and trailing parts beside it each draw their own segment of it, so a flat row
   reads as one rail end to end. No gap here for the same reason, since a gap would break the rail. */
.sd-tabs__bar {
  display: flex;
  min-width: 0;
}
.sd-tabs__bar[data-orientation="horizontal"] {
  flex-direction: row;
}
.sd-tabs__bar[data-orientation="vertical"] {
  flex-direction: column;
}

/* The scrollport around the list (see the tsx: flat tabs scroll, only contained ones may wrap).
   `overflow-x: auto` forces the CROSS axis to clip — CSS resolves a `visible` pair to `auto` — and
   a tab's focus ring is a `box-shadow` drawn OUTSIDE its box, so the ring would be shaved off top
   and bottom on every focused tab (WCAG 2.4.7, and nothing here would have caught it: axe reads the
   declaration, not what survives the clip). The padding gives the ring its room and the negative
   margin gives the space straight back, so the strip occupies exactly what it did before. The pair
   swaps axes with the orientation, because so does the clipped one. */
.sd-tabs__scroll[data-orientation="horizontal"] {
  flex: 1 1 auto;
  min-width: 0;
  padding-block: var(--sd-state-focus-ring-width);
  margin-block: calc(-1 * var(--sd-state-focus-ring-width));
}
/* contained has no rail, so the ring room can go on the inline axis too: the scrollport clips it
   there (`overflow-x`), and a contained tab's ring hugs a filled box at the strip's ends and, when
   wrapped, at every row's. A flat row sets no inline room of its own and takes ScrollArea's gutter,
   the larger of the ring and the tab's bled wash, with the matching negative margin; the pager is
   positioned, so it paints over the strip's overlapping room and keeps its whole hit area. */
.sd-tabs__scroll[data-variant="contained"][data-orientation="horizontal"] {
  padding-inline: var(--sd-state-focus-ring-width);
  margin-inline: calc(-1 * var(--sd-state-focus-ring-width));
}
/* page: the arrows scroll by one viewport, smoothly unless the reader asked for less motion. The
   scrollbar goes: the arrows are the affordance, and a classic scrollbar would sit under the list,
   inside the scrollport, and lift the list's rail off the pager's segment by its own height.
   (`scroll` keeps its scrollbar, since it is that mode's only pointer affordance; with `trailing`
   on a classic-scrollbar platform its rail segment sits that height below the list's. Known.) */
.sd-tabs__scroll[data-overflow="page"] {
  scroll-behavior: smooth;
  scrollbar-width: none;
}
@media (prefers-reduced-motion: reduce) {
  .sd-tabs__scroll[data-overflow="page"] {
    scroll-behavior: auto;
  }
}
.sd-tabs__scroll[data-orientation="vertical"] {
  /* The larger of the ring and a stacked tab's start-side bleed. */
  padding-inline: max(var(--sd-state-focus-ring-width), var(--sd-tabs-tab-state-layer-overhang));
  margin-inline: calc(-1 * max(var(--sd-state-focus-ring-width), var(--sd-tabs-tab-state-layer-overhang)));
}

.sd-tabs__list {
  display: flex;
  gap: var(--sd-tabs-list-gap);
  border-color: var(--sd-tabs-list-border);
}
/* `min-width: max-content` is what keeps the RAIL under the tabs that scrolled out of view: the
   list is block-level, so its width would otherwise be the scrollport's and the border-block-end
   would stop at the fold. The vertical twin needs no counterpart — a block box's height is already
   its content's. */
.sd-tabs__list[data-orientation="horizontal"] {
  flex-direction: row;
  min-width: max-content;
  border-block-end: var(--sd-tabs-list-border-width) solid var(--sd-tabs-list-border);
}
.sd-tabs__list[data-orientation="vertical"] {
  flex-direction: column;
  min-width: var(--sd-tabs-list-width-vertical);
  border-inline-end: var(--sd-tabs-list-border-width) solid var(--sd-tabs-list-border);
}
/* contained: no rail, since the selected tab's own fill carries the selection. After the orientation
   rules on purpose: equal specificity, so source order lets this remove the rail they draw. The tabs
   still sit flush, as the measured kiosk bar does: only the selected one is drawn. */
.sd-tabs__list[data-variant="contained"] {
  border: 0;
}
/* A flat or quiet tab's box is its label, at 0 on the one start line, with its wash bleeding past it
   (the tab rule below). Two overhangs between neighbours keep one tab's bled wash off the next
   tab's label. Horizontal only: stacked tabs bleed inline, which no block gap would part. */
.sd-tabs__list[data-variant="flat"][data-orientation="horizontal"],
.sd-tabs__list[data-variant="quiet"][data-orientation="horizontal"] {
  gap: calc(2 * var(--sd-tabs-tab-state-layer-overhang));
}
/* wrap (contained only, by type): as many rows as the tabs need. `min-width: 0` undoes the
   horizontal rule's `max-content`, which exists to keep a SCROLLING rail whole and would otherwise
   hold every tab on one line. Rows get their own gap, or one row's selected box would touch the next. */
.sd-tabs__list[data-overflow="wrap"] {
  flex-wrap: wrap;
  min-width: 0;
  row-gap: var(--sd-tabs-list-row-gap);
}
/* isFullWidth, wrapped: a grid of equal columns, as many as fit at `minTabWidth` (set inline on the
   root, the GridList idiom). `auto-fit`, not `auto-fill`: with fewer tabs than columns the empty
   tracks collapse, so the tabs still fill the row as `isFullWidth` promises. `min(…, 100%)` keeps one column from overflowing a row narrower than
   the minimum. The gaps stay the list's: tabs flush in a row, `row-gap` between rows. */
.sd-tabs__list[data-full-width][data-overflow="wrap"] {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(var(--sd-tabs-min-tab-width), 100%), 1fr));
}

/* pager — the page arrows. One part for both: which chevron is decided in the tsx, so no rule here
   is keyed to a direction (an arrow hidden at its end would otherwise leave its states unrendered).
   A square of the tab's own height, with the rail segment under it in a flat row. */
.sd-tabs__pager {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  padding: 0;
  color: var(--sd-tabs-pager-foreground);
  background: none;
  border: 0;
  font: inherit;
  cursor: pointer;
  outline: none;
}
.sd-tabs__pager[data-variant="flat"] {
  border-block-end: var(--sd-tabs-list-border-width) solid var(--sd-tabs-list-border);
}
.sd-tabs__pager[data-size="x-small"] {
  width: var(--sd-tabs-tab-min-height-x-small);
  font-size: var(--sd-tabs-pager-icon-size-x-small);
}
.sd-tabs__pager[data-size="small"] {
  width: var(--sd-tabs-tab-min-height-small);
  font-size: var(--sd-tabs-pager-icon-size-small);
}
.sd-tabs__pager[data-size="medium"] {
  width: var(--sd-tabs-tab-min-height-medium);
  font-size: var(--sd-tabs-pager-icon-size-medium);
}
/* The arrows follow the row to its logical ends under RTL; mirror the glyph with them, the
   Carousel idiom. */
.sd-tabs__pager:dir(rtl) {
  scale: -1 1;
}
.sd-tabs__pager::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--sd-tabs-tab-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-tabs__pager[data-hovered]::after {
  background: var(--sd-state-hover);
}
.sd-tabs__pager[data-pressed]::after {
  background: var(--sd-state-pressed);
}
/* Never a tab stop, but assistive tech or a script can still focus it, and then it must show. */
.sd-tabs__pager[data-focus-visible] {
  box-shadow: inset 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* trailing — the consumer's controls at the end of the row (search, expand). Spaced from the tabs
   by padding rather than a bar gap, so a flat row's rail segment runs under the space too. */
.sd-tabs__trailing {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--sd-tabs-trailing-gap);
}
.sd-tabs__trailing[data-orientation="horizontal"] {
  padding-inline-start: var(--sd-tabs-trailing-gap);
}
.sd-tabs__trailing[data-orientation="vertical"] {
  padding-block-start: var(--sd-tabs-trailing-gap);
}
.sd-tabs__trailing[data-variant="flat"][data-orientation="horizontal"] {
  border-block-end: var(--sd-tabs-list-border-width) solid var(--sd-tabs-list-border);
}
.sd-tabs__trailing[data-variant="flat"][data-orientation="vertical"] {
  border-inline-end: var(--sd-tabs-list-border-width) solid var(--sd-tabs-list-border);
}

.sd-tabs__tab {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding-block: var(--sd-tabs-tab-padding-block);
  color: var(--sd-tabs-tab-foreground);
  border-radius: var(--sd-tabs-tab-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  /* How far the state layer reaches past the box: a flat or quiet tab is a row whose only paint is
     its state fill, so its label sits at 0 and the wash bleeds (component-contract.md §6 rule 8;
     Collapsible is the reference shape). A contained tab is a box and keeps it inside. */
  --sd-tabs-tab-overhang-current: var(--sd-tabs-tab-state-layer-overhang);
  /* The wash each state lays over the tab: the surface wash, or on a contained tab's selected fill
     the one named for its ink, which goes away from that ink (contrast-contract.mjs § the state layer). */
  --sd-tabs-tab-state-hover-current: var(--sd-state-hover);
  --sd-tabs-tab-state-pressed-current: var(--sd-state-pressed);
  outline: none;
  cursor: pointer;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    color var(--sd-duration-moderate) var(--sd-easing-standard);
}
/* size — height. The label's font-size comes from the size-matched type role class
   (`sd-type-label-${size}`), the same uniform mapping Button and ToggleButton use. Only a contained
   tab takes inline padding (below). */
.sd-tabs__tab[data-size="x-small"] {
  min-height: var(--sd-tabs-tab-min-height-x-small);
}
.sd-tabs__tab[data-size="small"] {
  min-height: var(--sd-tabs-tab-min-height-small);
}
.sd-tabs__tab[data-size="medium"] {
  min-height: var(--sd-tabs-tab-min-height-medium);
}

/* The selected flat tab's bar: React Aria's SelectionIndicator, rendered on the selected tab only. It
   slides from the previous tab because React Aria animates every property it TRANSITIONS: the position
   is `translate`, and the length an explicit `width` (or `height`, vertical), a length a transition can
   reach, where the box two insets alone derive could not be interpolated. */
.sd-tabs__indicator {
  position: absolute;
  inset-block-end: calc(-1 * var(--sd-tabs-list-border-width));
  height: var(--sd-tabs-tab-indicator-size);
  background: var(--sd-tabs-tab-indicator-background);
  border-radius: var(--sd-tabs-tab-indicator-radius);
  corner-shape: round;
  /* A flat tab's box IS its label, so the bar spans the box (the vertical rule below replaces this). */
  inset-inline-start: 0;
  width: 100%;
  pointer-events: none;
  transition:
    translate var(--sd-duration-moderate) var(--sd-easing-standard),
    width var(--sd-duration-moderate) var(--sd-easing-standard),
    height var(--sd-duration-moderate) var(--sd-easing-standard);
}
/* Vertical: indicator runs down the inline-end edge, aligned with the list divider. */
.sd-tabs__indicator[data-orientation="vertical"] {
  inset-inline-start: auto;
  inset-inline-end: calc(-1 * var(--sd-tabs-list-border-width));
  inset-block-start: var(--sd-tabs-tab-indicator-inset-block);
  width: var(--sd-tabs-tab-indicator-size);
  height: calc(100% - 2 * var(--sd-tabs-tab-indicator-inset-block));
}
/* Interaction state-layer via ::before.
   ::before paints over the tab bg but under the label, so the tint composites
   cleanly (ADR-0009 state-layer). It reaches past the box by the overhang. */
.sd-tabs__tab::before {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline: calc(-1 * var(--sd-tabs-tab-overhang-current));
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-tabs__tab[data-hovered] {
  color: var(--sd-tabs-tab-foreground-hover);
}
.sd-tabs__tab[data-hovered]::before {
  background: var(--sd-tabs-tab-state-hover-current);
}
/* pressed after hovered so a press over a hovered tab reads as the deeper tint. */
.sd-tabs__tab[data-pressed]::before {
  background: var(--sd-tabs-tab-state-pressed-current);
}
.sd-tabs__tab[data-selected] {
  color: var(--sd-tabs-tab-foreground-selected);
}
/* The accent ink of a selected flat tab is derived at its floor, so it too rises to `text.DEFAULT`
   while hovered or pressed (contrast-contract.mjs § SURFACE_WASH_INKS); the indicator keeps the
   selection. A pressed tab with no hover (a key press) rises the same way. A contained tab's
   selected ink sits on its own fill and keeps it. */
.sd-tabs__tab[data-pressed],
.sd-tabs__tab[data-selected]:not([data-variant="contained"])[data-hovered],
.sd-tabs__tab[data-selected]:not([data-variant="contained"])[data-pressed] {
  color: var(--sd-tabs-tab-foreground-hover);
}
/* isFullWidth, one row: the tabs share it in equal cells, so a selected box spans its cell. A
   vertical list already spans its column. In the wrapped grid the column sizes the cell instead. */
.sd-tabs__tab[data-full-width][data-orientation="horizontal"] {
  flex: 1 1 0;
}
/* ...but never narrower than its label on a row that scrolls: an equal share smaller than the label
   would wrap it onto a second line inside a strip that exists to scroll instead. The wrapped grid
   is left to its columns, where a long label may wrap. */
.sd-tabs__tab[data-full-width][data-overflow="scroll"],
.sd-tabs__tab[data-full-width][data-overflow="page"] {
  min-width: max-content;
}

/* contained: the selected tab is a filled box on the control corner, the rest draw nothing at rest
   (their hover tint takes the same corner). The inline padding is a box's, the control inset ladder;
   a flat tab takes none. No indicator: the fill carries the selection. */
.sd-tabs__tab[data-variant="contained"] {
  border-radius: var(--sd-tabs-tab-radius-contained);
  corner-shape: superellipse(var(--sd-radius-curve));
  --sd-tabs-tab-overhang-current: 0px;
}
/* A stacked flat tab bleeds on its start side only: its end edge meets the rail and the bar. */
.sd-tabs__tab[data-orientation="vertical"]::before {
  inset-inline-end: 0;
}
.sd-tabs__tab[data-variant="contained"][data-size="x-small"] {
  padding-inline: var(--sd-tabs-tab-padding-inline-contained-x-small);
}
.sd-tabs__tab[data-variant="contained"][data-size="small"] {
  padding-inline: var(--sd-tabs-tab-padding-inline-contained-small);
}
.sd-tabs__tab[data-variant="contained"][data-size="medium"] {
  padding-inline: var(--sd-tabs-tab-padding-inline-contained-medium);
}
.sd-tabs__tab[data-variant="contained"][data-selected] {
  color: var(--sd-tabs-tab-foreground-contained-selected);
  background: var(--sd-tabs-tab-background-contained-selected);
  --sd-tabs-tab-state-hover-current: var(--sd-state-hover-on-accent);
  --sd-tabs-tab-state-pressed-current: var(--sd-state-pressed-on-accent);
}
/* `z-index: 1` lifts the ring over a flush neighbour: every tab is `position: relative`, so a later
   sibling (a contained tab's filled box) would otherwise paint over this one's ring. The ring is on
   the ::before, so it traces the same bled shape the wash does. */
.sd-tabs__tab[data-focus-visible] {
  z-index: 1;
}
.sd-tabs__tab[data-focus-visible]::before {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-tabs__tab[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

/* No padding: the panel paints nothing, so padding here would be indistinguishable from
   `.sd-tabs`'s own gap — the two stacked to 40px with neither owning it. The gap owns it. */
.sd-tabs__panel {
  flex: 1;
  min-width: 0;
  /* A region, not a line of text: its role class lends the font to what it holds and must not
     pad it, or every box inside moves one text inset in. Text placed here carries its own role. */
  padding-inline: 0;
  color: var(--sd-tabs-panel-foreground);
  outline: none;
}
.sd-tabs__panel[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
  border-radius: var(--sd-tabs-panel-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}

/* After the bar's own rule, which it must outrank at equal specificity: no transition, so React Aria
   takes no snapshot and the bar simply appears on the new tab. */
@media (prefers-reduced-motion: reduce) {
  .sd-tabs__indicator {
    transition: none;
  }
}

/* Quiet page sections carry selection in their ink alone. */
.sd-tabs__list[data-variant="quiet"] {
  border: 0;
}
/* The room is the larger of the ring and the bled wash, so neither is clipped at the strip's ends. */
.sd-tabs__scroll[data-variant="quiet"][data-orientation="horizontal"] {
  padding-inline: max(var(--sd-state-focus-ring-width), var(--sd-tabs-tab-state-layer-overhang));
  margin-inline: calc(-1 * max(var(--sd-state-focus-ring-width), var(--sd-tabs-tab-state-layer-overhang)));
}
.sd-tabs__tab[data-variant="quiet"][data-selected] {
  color: var(--sd-tabs-tab-foreground-quiet-selected);
}
.sd-tabs__tab[data-size="large"] {
  font-size: var(--sd-tabs-tab-font-size-large);
  min-height: var(--sd-tabs-tab-min-height-large);
}
.sd-tabs__tab[data-size="x-large"] {
  font-size: var(--sd-tabs-tab-font-size-large);
  min-height: var(--sd-tabs-tab-min-height-x-large);
}
.sd-tabs__tab[data-variant="contained"][data-size="large"] {
  padding-inline: var(--sd-tabs-tab-padding-inline-contained-large);
}
.sd-tabs__tab[data-variant="contained"][data-size="x-large"] {
  padding-inline: var(--sd-tabs-tab-padding-inline-contained-x-large);
}
.sd-tabs__pager[data-size="large"] {
  width: var(--sd-tabs-tab-min-height-large);
  font-size: var(--sd-tabs-pager-icon-size-large);
}
.sd-tabs__pager[data-size="x-large"] {
  width: var(--sd-tabs-tab-min-height-x-large);
  font-size: var(--sd-tabs-pager-icon-size-x-large);
}
